Item.method_code:
const { itemTypeName, getState } = options;
const state = getState();
const { selectedRows } = state.grid;
const id = selectedRows[0];
const { store, item } = await import('../jsBundles/store.es.js');
const isNew = item.isNew(itemTypeName, id);
const configId = options.rows.get(id, 'config_id');

if (isNew || !configId) {
	return;
}

const props = options.getProps();
const isAlreadyFavorited =
	options.favorites.filterFavorites(
		props.favorites,
		'Item',
		(favorite) => favorite.additional_data.id === configId
	).length > 0;

if (isAlreadyFavorited) {
	return;
}

const system = store.getState().system;
const { defaultLanguageCode, languages } = system;
const aliasIdentityId = system.user.identityId;

const row = options.rows.get(id);
const contextType = row['id@aras.type'] || options.itemTypeName;
const label = row.keyed_name;

const favoriteLocaleLabels =
	languages && defaultLanguageCode && languages.length > 1
		? languages.reduce((acc, { code }) => {
				if (code !== defaultLanguageCode) {
					acc[`label@aras.lang.${code}`] = label;
				}
				return acc;
			}, {})
		: {};

const newFavorite = {
	'@action': 'add',
	category: 'Item',
	contextType,
	label,
	ownedBy: aliasIdentityId,
	additional_data: { id: configId },
	quickAccessFlag: '1',
	...favoriteLocaleLabels
};

return aras.getMainWindow().ArasCore.Dialogs.openFavoriteDialog(newFavorite);
